def step(state, action):
    new_state = deepcopy(state)
    aid = action["id"]
    if aid == 1:
        # Find player shape (color 12 and 9) and move up by 5 rows
        pts12 = find_color(new_state, 12)
        if pts12:
            xs = [p[0] for p in pts12]
            ys = [p[1] for p in pts12]
            minx, maxx = min(xs), max(xs)
            miny, maxy = min(ys), max(ys)
            width = maxx - minx + 1
            height = 5  # known: 2 rows of 12, 3 rows of 9
            # Clear old shape area to color 3
            for y in range(miny, miny + height):
                for x in range(minx, minx + width):
                    new_state.grid[y][x] = 3
            # Place new shape 5 rows above
            new_miny = miny - 5
            # top 2 rows color 12
            for y in range(new_miny, new_miny + 2):
                for x in range(minx, minx + width):
                    new_state.grid[y][x] = 12
            # bottom 3 rows color 9
            for y in range(new_miny + 2, new_miny + 5):
                for x in range(minx, minx + width):
                    new_state.grid[y][x] = 9
        # Increment counter in the bottom two rows (row index height-3 and height-2)
        grid_h = len(new_state.grid) - 1
        for row_idx in (grid_h - 2, grid_h - 1):  # rows 61 and 62 for height 64
            row = new_state.grid[row_idx]
            # Find start of the counter block: first occurrence of 3 or 11
            start = -1
            for i, val in enumerate(row):
                if val in (3, 11):
                    start = i
                    break
            if start == -1:
                continue
            # Search forward to find first 11 in the block
            for i in range(start, len(row)):
                if row[i] == 11:
                    row[i] = 3
                    break
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

