def step(state, action):
    new_state = deepcopy(state)
    aid = action["id"]
    if aid == 1:
        # infer grid width from color 4 (covers full width)
        pts4 = find_color(new_state, 4)
        if not pts4:
            return new_state
        max_x = max(p[0] for p in pts4)
        width = max_x + 1
        height = len(new_state.grid) // width  # total rows

        # move player shape up by 5 rows
        pts12 = find_color(new_state, 12)
        if pts12:
            min_x = min(p[0] for p in pts12)
            max_x = max(p[0] for p in pts12)
            min_y = min(p[1] for p in pts12)
            shape_h = 5
            # clear old shape
            for y in range(min_y, min_y + shape_h):
                for x in range(min_x, max_x + 1):
                    new_state.grid[y * width + x] = 3
            # place new shape 5 rows above
            new_min_y = min_y - 5
            # top 2 rows = 12
            for y in range(new_min_y, new_min_y + 2):
                for x in range(min_x, max_x + 1):
                    new_state.grid[y * width + x] = 12
            # bottom 3 rows = 9
            for y in range(new_min_y + 2, new_min_y + 5):
                for x in range(min_x, max_x + 1):
                    new_state.grid[y * width + x] = 9

        # increment counter (leftmost 11 -> 3) in rows height-3 and height-2
        for row_idx in (height - 3, height - 2):
            row_start = row_idx * width
            for i in range(row_start, row_start + width):
                if new_state.grid[i] == 11:
                    new_state.grid[i] = 3
                    break
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

