# Helpers available: GridState, find_color, bbox, neighbors4, deepcopy

def step(state, action):
    new_state = deepcopy(state)
    aid = action["id"]
    if aid == 1:
        # Get border points to determine grid bounds
        border_pts = find_color(new_state, 4)  # color 4 is the outer border
        if not border_pts:
            return new_state
        min_x = min(p[0] for p in border_pts)
        max_x = max(p[0] for p in border_pts)
        min_y = min(p[1] for p in border_pts)
        max_y = max(p[1] for p in border_pts)

        # Find player shape (color 12)
        pts12 = find_color(new_state, 12)
        if pts12:
            pxs = [p[0] for p in pts12]
            pys = [p[1] for p in pts12]
            pminx = min(pxs)
            pmaxx = max(pxs)
            pminy = min(pys)
            # Clear old shape area (5 rows tall, 5 cols wide)
            for y in range(pminy, pminy+5):
                for x in range(pminx, pmaxx+1):
                    new_state[y][x] = 3
            # Place new shape 5 rows up
            new_pminy = pminy - 5
            for y in range(new_pminy, new_pminy+2):
                for x in range(pminx, pmaxx+1):
                    new_state[y][x] = 12
            for y in range(new_pminy+2, new_pminy+5):
                for x in range(pminx, pmaxx+1):
                    new_state[y][x] = 9

        # Increment counter: find rows that contain color 11, take the two lowest ones
        rows_with_11 = []
        for y in range(min_y, max_y+1):
            row_has_11 = False
            for x in range(min_x, max_x+1):
                if new_state[y][x] == 11:
                    row_has_11 = True
                    break
            if row_has_11:
                rows_with_11.append(y)
        if rows_with_11:
            rows_with_11 = sorted(set(rows_with_11), reverse=True)[:2]  # two bottom rows with 11
            for ry in rows_with_11:
                # Replace the first 11 found in this row with 3
                for x in range(min_x, max_x+1):
                    if new_state[ry][x] == 11:
                        new_state[ry][x] = 3
                        break
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

