# world_model.py
# Helpers available: GridState, find_color, bbox, neighbors4, deepcopy

def step(state, action):
    # Convert state to a mutable 2D list using indexing to avoid iteration issues.
    h = len(state)
    w = len(state[0])
    grid = [[state[y][x] for x in range(w)] for y in range(h)]

    aid = action["id"]
    if aid == 1:
        # Locate player shape: top row of 12 -> color 12
        player_y = None
        player_x = None
        for y in range(h):
            for x in range(w):
                if grid[y][x] == 12:
                    player_y = y
                    player_x = x
                    break
            if player_y is not None:
                break
        if player_y is not None:
            # Player is 5x5 block, 12 in rows player_y and player_y+1, 9 in player_y+2 to player_y+4
            # Clear old block
            for dy in range(5):
                for dx in range(5):
                    ny = player_y + dy
                    nx = player_x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if grid[ny][nx] in (12, 9):
                            grid[ny][nx] = 3
            # Place new block 5 rows up (if possible)
            new_y = player_y - 5
            if new_y >= 0:
                for dy in range(2):
                    for dx in range(5):
                        ny = new_y + dy
                        nx = player_x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            grid[ny][nx] = 12
                for dy in range(2, 5):
                    for dx in range(5):
                        ny = new_y + dy
                        nx = player_x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            grid[ny][nx] = 9
            # else: shape moved off-screen, perhaps win? but not yet.

        # Increment counter in the two bottom-most rows that contain 11.
        # Find all rows with 11
        rows_with_11 = []
        for y in range(h):
            if 11 in grid[y]:
                rows_with_11.append(y)
        # Take the two largest row indices (bottom rows)
        rows_with_11 = sorted(set(rows_with_11), reverse=True)[:2]
        for r in rows_with_11:
            row = grid[r]
            for x in range(w):
                if row[x] == 11:
                    row[x] = 3
                    break

    # Return a new GridState from the modified 2D list
    return GridState(grid)

def is_goal(state):
    return state.levels_completed >= state.win_levels

