# Helpers available: GridState, find_color, bbox, neighbors4, deepcopy

def step(state, action):
    # Extract grid bounds using border color 4
    border = find_color(state, 4)
    if not border:
        return deepcopy(state)
    min_x = min(p[0] for p in border)
    max_x = max(p[0] for p in border)
    min_y = min(p[1] for p in border)
    max_y = max(p[1] for p in border)
    h = max_y - min_y + 1
    w = max_x - min_x + 1

    # Create mutable grid copy
    grid = [[state[y][x] for x in range(min_x, max_x+1)] for y in range(min_y, max_y+1)]

    aid = action["id"]
    if aid == 1:
        # Locate player: topmost 12
        pts12 = find_color(state, 12)  # use original state because grid not yet mutated
        if pts12:
            px = min(p[0] for p in pts12)
            py = min(p[1] for p in pts12)
            # Clear old 5x5 block
            for dy in range(5):
                for dx in range(5):
                    ny = py + dy - min_y
                    nx = px + dx - min_x
                    if 0 <= ny < h and 0 <= nx < w:
                        grid[ny][nx] = 3
            # Place new block 5 rows up
            new_py = py - 5
            if new_py >= 0:
                for dy in range(2):
                    for dx in range(5):
                        ny = new_py + dy - min_y
                        nx = px + dx - min_x
                        if 0 <= ny < h and 0 <= nx < w:
                            grid[ny][nx] = 12
                for dy in range(2, 5):
                    for dx in range(5):
                        ny = new_py + dy - min_y
                        nx = px + dx - min_x
                        if 0 <= ny < h and 0 <= nx < w:
                            grid[ny][nx] = 9

        # Increment counter: find rows with 11, take bottom two (closest to bottom)
        rows_with_11 = []
        for y in range(h):
            if 11 in grid[y]:
                rows_with_11.append(y)
        rows_with_11 = sorted(set(rows_with_11), reverse=True)[:2]
        for r in rows_with_11:
            row = grid[r]
            for x in range(w):
                if row[x] == 11:
                    row[x] = 3
                    break

    return GridState(grid)

def is_goal(state):
    return state.levels_completed >= state.win_levels

