def step(state, action):
    new_state = deepcopy(state)
    if action["id"] == 1:
        # Move the special block (color 12/9) upward by its own height (5)
        block_cells = find_color(new_state, 12) + find_color(new_state, 9)
        if block_cells:
            # Compute bounding box of the block (inclusive)
            x0, y0, x1, y1 = bbox(block_cells)
            block_width = x1 - x0 + 1
            block_height = y1 - y0 + 1
            # Clear old block: fill with color 3
            for y in range(y0, y1+1):
                for x in range(x0, x1+1):
                    new_state.grid[y][x] = 3
            # Place new block shifted up by block_height
            new_y0 = y0 - block_height
            for i in range(block_height):
                y = new_y0 + i
                if 0 <= y < new_state.height:
                    for x in range(x0, x0 + block_width):
                        if 0 <= x < new_state.width:
                            color = 12 if i < 2 else 9
                            new_state.grid[y][x] = color
        # Increment the bottom green counter (rows 61,62): replace one 11 with 3
        if new_state.height > 61:
            for row_idx in (61, 62):
                row = new_state.grid[row_idx]
                # Find the boundary where 3 changes to 11
                for col in range(new_state.width - 1):
                    if row[col] == 3 and row[col + 1] == 11:
                        row[col + 1] = 3
                        break
    return new_state

