# world_model.py
# Helpers available: GridState, find_color, bbox, neighbors4, deepcopy

def _get_grid(state):
    # Try likely attribute names for the 2D color grid
    for name in ('frame', 'pixels', 'tiles', 'data', 'cells', 'rows', 'map', 'grid', 'board', 'layout'):
        try:
            grid = getattr(state, name)
            # quick check if iterable and contains rows
            if hasattr(grid, '__iter__') and len(grid) > 0 and hasattr(grid[0], '__iter__'):
                return grid
        except AttributeError:
            continue
    # fallback: maybe state itself is the grid (but we know it's not iterable)
    if hasattr(state, '__iter__'):
        return state
    return None

def step(state, action):
    new_state = deepcopy(state)
    grid = _get_grid(new_state)
    if grid is None:
        return new_state
    if action["id"] == 1:
        block_cells = find_color(grid, 12) + find_color(grid, 9)
        if block_cells:
            x0, y0, x1, y1 = bbox(block_cells)
            block_height = y1 - y0 + 1
            # clear old block
            for y in range(y0, y1+1):
                for x in range(x0, x1+1):
                    grid[y][x] = 3
            # place new block shifted up by its height
            new_y0 = y0 - block_height
            for i in range(block_height):
                y = new_y0 + i
                if 0 <= y < new_state.height:
                    for x in range(x0, x0 + (x1 - x0 + 1)):
                        if 0 <= x < new_state.width:
                            color = 12 if i < 2 else 9
                            grid[y][x] = color
        # increment counter on bottom two rows
        if new_state.height > 61:
            for row_idx in (61, 62):
                row = grid[row_idx]
                for col in range(new_state.width - 1):
                    if row[col] == 3 and row[col + 1] == 11:
                        row[col + 1] = 3
                        break
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

