# Helpers available: GridState, find_color, bbox, neighbors4, deepcopy

def decode_rle(rle_rows):
    grid = []
    for row_str in rle_rows:
        row = []
        if row_str:
            tokens = row_str.split(',')
            for tok in tokens:
                if ':' in tok:
                    color, count = tok.split(':')
                    row.extend([int(color)] * int(count))
        grid.append(row)
    return grid

def encode_rle(grid):
    rle_rows = []
    for row in grid:
        if not row:
            rle_rows.append('')
            continue
        compressed = []
        prev = row[0]
        count = 1
        for i in range(1, len(row)):
            if row[i] == prev:
                count += 1
            else:
                compressed.append(f"{prev}:{count}")
                prev = row[i]
                count = 1
        compressed.append(f"{prev}:{count}")
        rle_rows.append(','.join(compressed))
    return rle_rows

def step(state, action):
    new_state = deepcopy(state)
    rle = new_state.frame_rle
    grid = decode_rle(rle)
    if action["id"] == 1:
        block_cells = find_color(grid, 12) + find_color(grid, 9)
        if block_cells:
            x0, y0, x1, y1 = bbox(block_cells)
            # Clear old block
            for y in range(y0, y1+1):
                for x in range(x0, x1+1):
                    grid[y][x] = 3
            block_height = y1 - y0 + 1
            new_y0 = y0 - block_height
            for i in range(block_height):
                y = new_y0 + i
                if 0 <= y < len(grid):
                    for x in range(x0, x1+1):
                        if 0 <= x < len(grid[0]):
                            grid[y][x] = 12 if i < 2 else 9
        # Increment counter on bottom rows (last two rows)
        if len(grid) > 61:
            for row_idx in (61, 62):
                row = grid[row_idx]
                for col in range(len(grid[0]) - 1):
                    if row[col] == 3 and row[col + 1] == 11:
                        row[col + 1] = 3
                        break
    new_rle = encode_rle(grid)
    new_state.frame_rle = new_rle
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

