# Helpers available: GridState, find_color, bbox, neighbors4, deepcopy

def decode_rle(rle_rows):
    grid = []
    for row_str in rle_rows:
        row = []
        if row_str:
            for token in row_str.split(','):
                if ':' in token:
                    color, cnt = token.split(':')
                    row.extend([int(color)] * int(cnt))
        grid.append(row)
    return grid

def encode_rle(grid):
    rle_rows = []
    for row in grid:
        if not row:
            rle_rows.append('')
            continue
        tokens = []
        i = 0
        while i < len(row):
            j = i
            while j < len(row) and row[j] == row[i]:
                j += 1
            tokens.append(f"{row[i]}:{j-i}")
            i = j
        rle_rows.append(','.join(tokens))
    return rle_rows

def find_block(grid):
    """Find the moving block (12 and 9). Return (top, bottom, left, right) inclusive."""
    cells_12 = find_color(grid, 12)
    if not cells_12:
        return None
    x0, y0, x1, y1 = bbox(cells_12)
    block_top = y0
    block_bottom = y1  # will possibly extend downward
    # expand down while rows are all 9 in the same x-range
    for y in range(y1 + 1, len(grid)):
        row_segment = grid[y][x0:x1+1]
        if all(v == 9 for v in row_segment):
            block_bottom = y
        else:
            break
    return (block_top, block_bottom, x0, x1)

def step(state, action):
    new_state = deepcopy(state)
    # Access grid
    if hasattr(new_state, 'snapshot'):
        rle_rows = new_state.snapshot.get('frame_rle')
    else:
        try:
            rle_rows = new_state.frame_rle
        except AttributeError:
            return new_state
    if rle_rows is None:
        return new_state
    grid = decode_rle(rle_rows)

    if action["id"] == 1:
        block_rect = find_block(grid)
        if block_rect is None:
            return new_state
        top, bottom, left, right = block_rect
        block_height = bottom - top + 1
        block_width = right - left + 1
        new_top = top - block_height
        if new_top < 0:
            return new_state  # can't move
        # Check target area: all must be 3
        target_all_3 = True
        for y in range(new_top, new_top + block_height):
            for x in range(left, right + 1):
                if grid[y][x] != 3:
                    target_all_3 = False
                    break
            if not target_all_3:
                break
        if not target_all_3:
            return new_state
        # Save pattern
        pattern = [[grid[y][x] for x in range(left, right+1)] for y in range(top, bottom+1)]
        # Clear old block area
        for y in range(top, bottom+1):
            for x in range(left, right+1):
                grid[y][x] = 3
        # Place block at new position
        for dy in range(block_height):
            for dx in range(block_width):
                grid[new_top + dy][left + dx] = pattern[dy][dx]
        # Increment green counter on rows 61 and 62
        if len(grid) > 61:
            for row_idx in (61, 62):
                row = grid[row_idx]
                for col in range(len(row) - 1):
                    if row[col] == 3 and row[col+1] == 11:
                        row[col+1] = 3
                        break
    # Other actions (2,3,4) currently undefined: do nothing

    # Encode grid back to RLE
    new_rle = encode_rle(grid)
    if hasattr(new_state, 'snapshot'):
        new_state.snapshot['frame_rle'] = new_rle
    else:
        try:
            new_state.frame_rle = new_rle
        except AttributeError:
            pass
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

