def _grid_dims(state):
    # collect all cells of any color to infer grid size
    all_cells = []
    for color in range(16):
        cells = find_color(state, color)
        if cells:
            all_cells.extend(cells)
    if not all_cells:
        return 0, 0
    x0, y0, x1, y1 = bbox(all_cells)
    return x1 + 1, y1 + 1

def step(state, action):
    new_state = deepcopy(state)
    W, H = _grid_dims(new_state)
    if W == 0 or H == 0:
        return new_state

    # find block bounding box (colors 12 and 9)
    block_cells = find_color(new_state, 12) + find_color(new_state, 9)
    if not block_cells:
        return new_state
    bx0, by0, bx1, by1 = bbox(block_cells)
    w = bx1 - bx0 + 1
    h = by1 - by0 + 1

    # direction offset (block height/width step)
    dx = dy = 0
    if action["id"] == 1:
        dy = -h
    elif action["id"] == 2:
        dy = h
    elif action["id"] == 3:
        dx = -w
    elif action["id"] == 4:
        dx = w
    else:
        return new_state

    tx0 = bx0 + dx
    ty0 = by0 + dy
    tx1 = tx0 + w - 1
    ty1 = ty0 + h - 1

    # out of bounds
    if tx0 < 0 or ty0 < 0 or tx1 >= W or ty1 >= H:
        return new_state

    # target must be all background (3)
    for y in range(ty0, ty1 + 1):
        for x in range(tx0, tx1 + 1):
            if new_state[y][x] != 3:
                return new_state

    # save pattern
    pattern = [[new_state[y][x] for x in range(bx0, bx1 + 1)] for y in range(by0, by1 + 1)]
    # erase old block
    for y in range(by0, by1 + 1):
        for x in range(bx0, bx1 + 1):
            new_state[y][x] = 3
    # place at new position
    for dy2 in range(h):
        for dx2 in range(w):
            new_state[ty0 + dy2][tx0 + dx2] = pattern[dy2][dx2]

    # increment green counter on rows 61,62 if they exist
    if H >= 62:
        for r in (61, 62):
            # change the first green (11) cell to background (3)
            row = new_state[r]
            for x in range(W):
                if row[x] == 11:
                    row[x] = 3
                    break

    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

