# world_model.py

def step(state, action):
    new_state = deepcopy(state)
    if action["id"] == 1:
        # Determine grid bounds from all background cells (3)
        bg_cells = find_color(new_state, 3)
        if not bg_cells:
            return new_state
        x0_all, y0_all, x1_all, y1_all = bbox(bg_cells)
        # Find block cells (12 and 9)
        block_cells = find_color(new_state, 12) + find_color(new_state, 9)
        if not block_cells:
            return new_state
        x0, y0, x1, y1 = bbox(block_cells)
        block_height = y1 - y0 + 1
        new_y0 = y0 - block_height
        if new_y0 < 0:
            return new_state
        # Check target area all 3
        for y in range(new_y0, new_y0 + block_height):
            for x in range(x0, x1 + 1):
                if new_state[y][x] != 3:
                    return new_state
        # Save pattern
        pattern = [[new_state[y][x] for x in range(x0, x1+1)] for y in range(y0, y1+1)]
        # Clear old area
        for y in range(y0, y1+1):
            for x in range(x0, x1+1):
                new_state[y][x] = 3
        # Place block at new position
        for dy in range(block_height):
            for dx in range(x1 - x0 + 1):
                new_state[new_y0 + dy][x0 + dx] = pattern[dy][dx]
        # Increment green counter on rows 61,62 if within bounds
        if y1_all >= 62:  # row 62 exists, so rows 61,62 exist
            for row_idx in (61, 62):
                row = new_state[row_idx]
                for col in range(1, x1_all+1):
                    if row[col] == 11 and row[col-1] == 3:
                        row[col] = 3
                        break  # only one increment per row
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

