from copy import deepcopy

def update_progress(state):
    grid = state.grid
    h = len(grid)
    w = len(grid[0])
    for y in range(h):
        row = grid[y]
        if 11 not in row:
            continue
        i = 0
        while i < w and row[i] != 3:
            i += 1
        if i == w:
            continue
        j = i
        while j < w and row[j] == 3:
            j += 1
        n = j - i
        if j >= w or row[j] != 11:
            continue
        k = j
        while k < w and row[k] == 11:
            k += 1
        m = k - j
        n_new = n + 1
        m_new = m - 1
        if m_new < 0:
            continue
        left = row[:i]
        middle = [3]*n_new + [11]*m_new
        right = row[k:]
        new_row = left + middle + right
        if len(new_row) < w:
            new_row += [0]*(w - len(new_row))
        elif len(new_row) > w:
            new_row = new_row[:w]
        grid[y] = new_row
        if y+1 < h and 11 in grid[y+1]:
            grid[y+1] = list(new_row)
        break

def step(state, action):
    new_state = deepcopy(state)
    action_id = int(action["id"]) if isinstance(action, dict) else int(action)
    cells_12 = new_state.find_color(12)
    cells_9 = new_state.find_color(9)
    block_cells = cells_12 + cells_9
    if not block_cells:
        return new_state
    xs = [c[0] for c in block_cells]
    ys = [c[1] for c in block_cells]
    min_x, min_y = min(xs), min(ys)
    max_x, max_y = max(xs), max(ys)
    block_w = max_x - min_x + 1
    block_h = max_y - min_y + 1
    dx, dy = 0, 0
    if action_id == 1:
        dy = -5
    elif action_id == 2:
        dy = 5
    elif action_id == 3:
        dx = -5
    elif action_id == 4:
        dx = 5
    else:
        return new_state
    new_min_x = min_x + dx
    new_min_y = min_y + dy
    grid = new_state.grid
    h = len(grid)
    w = len(grid[0])
    if new_min_x < 0 or new_min_y < 0 or new_min_x + block_w > w or new_min_y + block_h > h:
        return new_state
    for y in range(new_min_y, new_min_y + block_h):
        for x in range(new_min_x, new_min_x + block_w):
            if grid[y][x] != 3:
                return new_state
    pattern = {}
    for x, y in block_cells:
        pattern[(x - min_x, y - min_y)] = grid[y][x]
    for y in range(min_y, min_y + block_h):
        for x in range(min_x, min_x + block_w):
            grid[y][x] = 3
    for (rx, ry), color in pattern.items():
        nx = new_min_x + rx
        ny = new_min_y + ry
        grid[ny][nx] = color
    update_progress(new_state)
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

