def update_progress(state):
    # state is a GridState that supports row assignment
    h = state.height if hasattr(state, 'height') else len(state)
    w = state.width if hasattr(state, 'width') else len(state[0])
    for y in range(h):
        row = state[y]
        if 11 not in row:
            continue
        i = 0
        while i < w and row[i] != 3:
            i += 1
        if i == w:
            continue
        j = i
        while j < w and row[j] == 3:
            j += 1
        n = j - i
        if j >= w or row[j] != 11:
            continue
        k = j
        while k < w and row[k] == 11:
            k += 1
        m = k - j
        n_new = n + 1
        m_new = m - 1
        if m_new < 0:
            continue
        left = row[:i]
        middle = [3]*n_new + [11]*m_new
        right = row[k:]
        new_row = left + middle + right
        if len(new_row) < w:
            new_row += [0]*(w - len(new_row))
        elif len(new_row) > w:
            new_row = new_row[:w]
        state[y] = new_row
        if y+1 < h and 11 in state[y+1]:
            state[y+1] = list(new_row)
        break

def step(state, action):
    new_state = deepcopy(state)
    action_id = int(action["id"]) if isinstance(action, dict) else int(action)

    # Get dimensions
    try:
        w = new_state.width
        h = new_state.height
    except AttributeError:
        # Fallback: compute from cells of color 4 (background)
        cells4 = find_color(new_state, 4)
        if cells4:
            w = max(c[0] for c in cells4) + 1
            h = max(c[1] for c in cells4) + 1
        else:
            # if no color 4, assume 64x64
            w, h = 64, 64

    block_cells = find_color(new_state, 12) + find_color(new_state, 9)
    if not block_cells:
        return new_state

    dx, dy = 0, 0
    if action_id == 1:
        dy = -5
    elif action_id == 2:
        dy = 5
    elif action_id == 3:
        dx = -5
    elif action_id == 4:
        dx = 5
    else:
        return new_state

    # Check destination cells
    for (x, y) in block_cells:
        nx = x + dx
        ny = y + dy
        if nx < 0 or ny < 0 or nx >= w or ny >= h:
            return new_state
        if new_state[ny][nx] != 3:
            return new_state

    # Perform move
    # First, save colors and erase old positions
    for (x, y) in block_cells:
        # store original color
        col = state[y][x]
        new_state[y][x] = 3
        new_state[y+dy][x+dx] = col

    update_progress(new_state)
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

