        if 11 not in row:
            continue
        i = 0
        while i < w and row[i] != 3:
            i += 1
        if i == w:
            continue
        j = i
        while j < w and row[j] == 3:
            j += 1
        n = j - i
        if j >= w or row[j] != 11:
            continue
        k = j
        while k < w and row[k] == 11:
            k += 1
        m = k - j
        n_new = n + 1
        m_new = m - 1
        if m_new < 0:
            continue
        left = row[:i]
        middle = [3]*n_new + [11]*m_new
        right = row[k:]
        new_row = left + middle + right
        if len(new_row) < w:
            new_row += [0]*(w - len(new_row))
        elif len(new_row) > w:
            new_row = new_row[:w]
        state[y] = new_row
        if y+1 < h and 11 in state[y+1]:
            state[y+1] = list(new_row)
        break

