    if not block_cells:
        return new_state

    dx, dy = 0, 0
    if action_id == 1:
        dy = -5
    elif action_id == 2:
        dy = 5
    elif action_id == 3:
        dx = -5
    elif action_id == 4:
        dx = 5
    else:
        return new_state

    # Check destination cells
    for (x, y) in block_cells:
        nx = x + dx
