    for color in range(16):
        cells = find_color(state, color)
        for x, y in cells:
            grid[y][x] = color
    return grid

def update_progress_grid(grid):
    dim = len(grid)
    for y in range(dim):
        row = grid[y]
        if 11 not in row:
            continue
        i = 0
        while i < dim and row[i] != 3:
            i += 1
        if i == dim:
            continue
        j = i
        while j < dim and row[j] == 3:
            j += 1
        if j >= dim or row[j] != 11:
            continue
        k = j
        while k < dim and row[k] == 11:
            k += 1
        n = j - i
        m = k - j
        if m == 0:
            continue
        # Extend 3 by 1, shrink 11 by 1
        n_new = n + 1
        m_new = m - 1
        left = row[:i]
        middle = [3] * n_new + [11] * m_new
        right = row[k:]
        new_row = left + middle + right
        if len(new_row) < dim:
            new_row += [0] * (dim - len(new_row))
        else:
            new_row = new_row[:dim]
        grid[y] = new_row
        # Duplicate to paired row if present
        if y + 1 < dim and 11 in grid[y + 1]:
            grid[y + 1] = list(new_row)
        break

