    dx, dy = 0, 0
    if action_id == 1:
        dy = -5
    elif action_id == 2:
        dy = 5
    elif action_id == 3:
        dx = -5
    elif action_id == 4:
        dx = 5
    else:
        return state
    # Check destination cells
    for (x, y, c) in block_cells:
        nx = x + dx
        ny = y + dy
        if nx < 0 or nx >= 64 or ny < 0 or ny >= 64:
            return state
        if grid[ny][nx] != 3:
            return state
    # Perform move on grid
    for (x, y, c) in block_cells:
        grid[y][x] = 3
        grid[y + dy][x + dx] = c
    update_progress_grid(grid)
    # Build new GridState from grid
    new_state = GridState(grid)
    return new_state

def is_goal(state):
    return state.levels_completed >= state.win_levels

