def update_progress_flat(data, dim=64):
    # find progress bar rows (color 11) and extend color 3
    for y in range(dim):
        start = y * dim
        row = data[start:start+dim]
        if 11 not in row:
            continue
        i = 0
        while i < dim and row[i] != 3:
            i += 1
        if i == dim:
            continue
        j = i
        while j < dim and row[j] == 3:
            j += 1
        if j >= dim or row[j] != 11:
            continue
        k = j
        while k < dim and row[k] == 11:
            k += 1
        n = j - i
        m = k - j
        if m == 0:
            continue
        n_new = n + 1
        m_new = m - 1
        # modify the flat data in place
        for idx in range(i, i + n_new):
            data[start + idx] = 3
        for idx in range(i + n_new, i + n_new + m_new):
            data[start + idx] = 11
        # duplicate effect to next row if it also has 11
        if y + 1 < dim:
            next_start = (y+1) * dim
            next_row = data[next_start:next_start+dim]
            if 11 in next_row:
                # copy the modified row
                data[next_start:next_start+dim] = data[start:start+dim]
        break

def step(state, action):
    new_state = deepcopy(state)
    action_id = int(action["id"]) if isinstance(action, dict) else int(action)
    # build flat array from state
    dim = 64
    data = [0] * (dim * dim)
    for color in range(16):
        cells = find_color(new_state, color)
        for (x, y) in cells:
            data[y * dim + x] = color
    # find block
    block = []
    for y in range(dim):
        start = y * dim
        for x in range(dim):
            c = data[start + x]
            if c in (12, 9):
                block.append((x, y, c))
    if not block:
        return new_state
    dx, dy = 0, 0
    if action_id == 1:
        dy = -5
    elif action_id == 2:
        dy = 5
    elif action_id == 3:
        dx = -5
    elif action_id == 4:
        dx = 5
    else:
        return new_state
    # check destination
    for (x, y, c) in block:
        nx, ny = x + dx, y + dy
        if not (0 <= nx < dim and 0 <= ny < dim):
            return new_state
        if data[ny * dim + nx] != 3:
            return new_state
    # move
    for (x, y, c) in block:
        data[y * dim + x] = 3
        data[(y + dy) * dim + (x + dx)] = c
    update_progress_flat(data, dim)
    # build new GridState from flat data
    return GridState(data)

def is_goal(state):
    return state.levels_completed >= state.win_levels

